var v=SugarCube.State.variables;
var locs={};
try{ for(var id in v.npcs){ var n=v.npcs[id]; if(n&&n.name) locs[n.name]=n.current_location; } }catch(e){}
return JSON.stringify(locs);

const out=[];
for(const el of document.querySelectorAll('*')){
  const cs=getComputedStyle(el);
  if(cs.cursor!=='pointer'||cs.display==='none')continue;
  const r=el.getBoundingClientRect();
  if(r.width<40||r.height<40||r.x<316)continue;
  const txt=(el.textContent||'').trim().slice(0,20);
  out.push({t:txt,x:Math.round(r.x+r.width/2),y:Math.round(r.y+r.height/2)});
}
const seen={},u=[];for(const o of out){const k=o.t+o.x;if(!seen[k]){seen[k]=1;u.push(o);}}
return JSON.stringify(u.slice(0,12));

const out=[];
for(const a of document.querySelectorAll('a, .link-internal, [onclick]')){
  const r=a.getBoundingClientRect();
  const t=(a.textContent||'').trim();
  if(t && r.x>316 && r.width>20) out.push({t:t.slice(0,28),x:Math.round(r.x+r.width/2),y:Math.round(r.y+r.height/2)});
}
return JSON.stringify(out.filter(o=>/Tease|Flash|Help|Leave/.test(o.t)));

const out=[];
for(const el of document.querySelectorAll('*')){
  const t=(el.textContent||'').trim();
  if(t!=='Tease him ❤️‍🔥' && t!=='Flash him 👀') continue;
  const cs=getComputedStyle(el);
  const r=el.getBoundingClientRect();
  out.push({t:t.slice(0,18),tag:el.tagName,cls:el.className,cursor:cs.cursor,x:Math.round(r.x+r.width/2),y:Math.round(r.y+r.height/2)});
}
return JSON.stringify(out);
